/*
 * P3R Native Android AOT Runtime: Guest CPU Implementation
 * Matches Recomp ABI v2 (Bloodborne-Android upstream cpu/guest_cpu_aot.cpp)
 * Freestanding implementation compatible with Bionic and ELF loading.
 */

#include "guest_cpu.h"

// External dispatch table generated by p3r_recomp.py
extern const size_t g_bbr_unit_count;
extern const RecompUnit g_bbr_units[];

void bbr_init_guest_state(GuestState* state, void* stack_base, size_t stack_size, uint64_t mem_base) {
    if (!state) return;

    // Zero entire GuestState
    uint8_t* p = (uint8_t*)state;
    for (size_t i = 0; i < sizeof(GuestState); i++) {
        p[i] = 0;
    }

    state->mem_base = mem_base;
    state->trap_code = 0;
    state->exit_code = 0;

    // Initialize 16-byte aligned guest stack pointer
    if (stack_base && stack_size > 64) {
        uintptr_t sp = (uintptr_t)stack_base + stack_size - 32;
        sp &= ~0xFULL; // 16-byte alignment (SysV AMD64 requirement)
        state->gregs[GUEST_RSP] = (uint64_t)sp;
        state->gregs[GUEST_RBP] = (uint64_t)sp;
    }
}

void bbr_dispatch(GuestState* state, uint64_t target_vaddr) {
    if (!state) return;
    state->rip = target_vaddr;

    bbr_func_t target_func = bbr_lookup(target_vaddr);
    if (target_func) {
        target_func(state);
    } else {
        bbr_trap(state, BBR_TRAP_MISS);
    }
}

void bbr_trap(GuestState* state, uint64_t trap_code) {
    if (!state) return;
    state->trap_code = trap_code;
    state->exit_code = 1;
}

uint64_t bbr_run_entry(GuestState* state, uint64_t entry_vaddr) {
    if (!state) return 0;
    bbr_dispatch(state, entry_vaddr);
    // SysV AMD64 return value convention: return register is RAX
    return state->gregs[GUEST_RAX];
}

/*
 * Freestanding 128-bit Integer Division Runtime for AArch64
 * Resolves compiler-rt symbols emitted by LLVM for 128-bit operations.
 */
typedef unsigned __int128 u128;
typedef __int128 s128;

static u128 udivmod128(u128 num, u128 den, u128* rem) {
    if (den == 0) {
        if (rem) *rem = 0;
        return 0;
    }
    u128 quot = 0;
    u128 r = 0;
    for (int i = 127; i >= 0; i--) {
        r = (r << 1) | ((num >> i) & 1);
        if (r >= den) {
            r -= den;
            quot |= ((u128)1 << i);
        }
    }
    if (rem) *rem = r;
    return quot;
}

u128 __udivti3(u128 a, u128 b) {
    return udivmod128(a, b, 0);
}

u128 __umodti3(u128 a, u128 b) {
    u128 r = 0;
    udivmod128(a, b, &r);
    return r;
}

s128 __divti3(s128 a, s128 b) {
    int neg = 0;
    if (a < 0) { a = -a; neg = !neg; }
    if (b < 0) { b = -b; neg = !neg; }
    u128 q = udivmod128((u128)a, (u128)b, 0);
    return neg ? -(s128)q : (s128)q;
}

s128 __modti3(s128 a, s128 b) {
    int neg = 0;
    if (a < 0) { a = -a; neg = 1; }
    if (b < 0) { b = -b; }
    u128 r = 0;
    udivmod128((u128)a, (u128)b, &r);
    return neg ? -(s128)r : (s128)r;
}
